import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  ActivityIndicator,
  Animated,
  Easing,
  Image,
  KeyboardAvoidingView,
  Linking,
  Modal,
  Platform,
  Pressable,
  SafeAreaView,
  ScrollView,
  StatusBar,
  StyleSheet,
  Text,
  TextInput,
  View,
} from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import * as Clipboard from 'expo-clipboard';
import { LinearGradient } from 'expo-linear-gradient';
import { useFonts } from 'expo-font';
import {
  DMSerifDisplay_400Regular,
  DMSerifDisplay_400Regular_Italic,
} from '@expo-google-fonts/dm-serif-display';
import { DMMono_400Regular, DMMono_500Medium } from '@expo-google-fonts/dm-mono';
import {
  Outfit_300Light,
  Outfit_400Regular,
  Outfit_500Medium,
  Outfit_600SemiBold,
  Outfit_700Bold,
} from '@expo-google-fonts/outfit';
import Svg, {
  Circle,
  Line,
  Path,
  Polygon,
  Polyline,
  Rect,
} from 'react-native-svg';

const CHAVE_PIX = 'e87306f1-8148-422b-a199-b2deb63fa194';
const LS_SALDO = 'foco_saldo';
const LS_REWARDS = 'foco_rewards';
const LS_THEME = 'foco_theme';
const MAX_REWARDS = 3;
const QR_URI = 'data:image/jpeg;base64,';
const RING_CIRCUMFERENCE = 2 * Math.PI * 46;

const FONT = {
  serif: 'DMSerifDisplay_400Regular',
  serifItalic: 'DMSerifDisplay_400Regular_Italic',
  mono: 'DMMono_400Regular',
  monoMedium: 'DMMono_500Medium',
  bodyLight: 'Outfit_300Light',
  body: 'Outfit_400Regular',
  bodyMedium: 'Outfit_500Medium',
  bodySemi: 'Outfit_600SemiBold',
  bodyBold: 'Outfit_700Bold',
};

const LIGHT = {
  bg: '#f0f7f3',
  bg2: '#d9eee4',
  ink: '#0d2e1c',
  ink2: '#255237',
  ink3: '#6a9a7e',
  card: '#ffffff',
  card2: '#f5fbf7',
  border: 'rgba(13,46,28,0.12)',
  accent: '#1a7a45',
  accent2: '#135c33',
  accentL: 'rgba(26,122,69,0.12)',
  green: '#0f5c30',
  greenL: 'rgba(15,92,48,0.12)',
  greenBright: '#22c064',
};

const DARK = {
  bg: '#07150e',
  bg2: '#0d2418',
  ink: '#dff2e9',
  ink2: '#96ccb0',
  ink3: '#4d8a64',
  card: '#0f2b1a',
  card2: '#0b2014',
  border: 'rgba(150,204,176,0.13)',
  accent: '#22c064',
  accent2: '#1aa855',
  accentL: 'rgba(34,192,100,0.15)',
  green: '#22c064',
  greenL: 'rgba(34,192,100,0.15)',
  greenBright: '#5dffaa',
};

function makeStars() {
  const result = [];
  for (let i = 0; i < 100; i += 1) {
    result.push({
      id: i,
      left: `${(Math.random() * (i < 90 ? 100 : 90)).toFixed(2)}%`,
      top: `${(Math.random() * (i < 90 ? 100 : 90)).toFixed(2)}%`,
      size: i < 90 ? Math.random() * 2.2 + 0.6 : Math.random() * 2 + 2,
      opacity: i < 90 ? Math.random() * 0.5 + 0.3 : Math.random() * 0.3 + 0.5,
      sparkle: i >= 90,
    });
  }
  return result;
}

function AppIcon({ type, size = 20, color = '#255237', strokeWidth = 1.8 }) {
  const common = { stroke: color, strokeWidth, fill: 'none', strokeLinecap: 'round', strokeLinejoin: 'round' };
  return (
    <Svg width={size} height={size} viewBox="0 0 24 24">
      {type === 'star' && <Path {...common} d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z" />}
      {type === 'timer' && (
        <>
          <Circle {...common} cx="12" cy="13" r="9" />
          <Path {...common} d="M12 7v6l4 2" />
          <Path {...common} d="M8 2h8" />
        </>
      )}
      {type === 'info' && (
        <>
          <Circle {...common} cx="12" cy="12" r="10" />
          <Line {...common} x1="12" y1="8" x2="12" y2="12" />
          <Line {...common} x1="12" y1="16" x2="12.01" y2="16" />
        </>
      )}
      {type === 'left' && <Polyline {...common} points="15 18 9 12 15 6" />}
      {type === 'right' && <Polyline {...common} points="9 18 15 12 9 6" />}
      {type === 'plus' && (
        <>
          <Line {...common} x1="12" y1="5" x2="12" y2="19" />
          <Line {...common} x1="5" y1="12" x2="19" y2="12" />
        </>
      )}
      {type === 'close' && (
        <>
          <Line {...common} x1="18" y1="6" x2="6" y2="18" />
          <Line {...common} x1="6" y1="6" x2="18" y2="18" />
        </>
      )}
      {type === 'check' && <Polyline {...common} points="20 6 9 17 4 12" />}
      {type === 'copy' && (
        <>
          <Rect {...common} x="9" y="9" width="13" height="13" rx="2" ry="2" />
          <Path {...common} d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" />
        </>
      )}
      {type === 'play' && <Polygon points="5 3 19 12 5 21 5 3" fill={color} stroke="none" />}
      {type === 'stop' && <Rect x="5" y="5" width="14" height="14" rx="2" fill={color} stroke="none" />}
      {type === 'pause' && (
        <>
          <Rect x="6" y="4" width="4" height="16" fill={color} stroke="none" />
          <Rect x="14" y="4" width="4" height="16" fill={color} stroke="none" />
        </>
      )}
      {type === 'sun' && (
        <>
          <Circle {...common} cx="12" cy="12" r="5" />
          <Line {...common} x1="12" y1="1" x2="12" y2="3" />
          <Line {...common} x1="12" y1="21" x2="12" y2="23" />
          <Line {...common} x1="4.22" y1="4.22" x2="5.64" y2="5.64" />
          <Line {...common} x1="18.36" y1="18.36" x2="19.78" y2="19.78" />
          <Line {...common} x1="1" y1="12" x2="3" y2="12" />
          <Line {...common} x1="21" y1="12" x2="23" y2="12" />
          <Line {...common} x1="4.22" y1="19.78" x2="5.64" y2="18.36" />
          <Line {...common} x1="18.36" y1="5.64" x2="19.78" y2="4.22" />
        </>
      )}
      {type === 'moon' && <Path {...common} d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" />}
    </Svg>
  );
}

export default function App() {
  const [fontsLoaded] = useFonts({
    DMSerifDisplay_400Regular,
    DMSerifDisplay_400Regular_Italic,
    DMMono_400Regular,
    DMMono_500Medium,
    Outfit_300Light,
    Outfit_400Regular,
    Outfit_500Medium,
    Outfit_600SemiBold,
    Outfit_700Bold,
  });

  const [loaded, setLoaded] = useState(false);
  const [page, setPage] = useState('home');
  const [saldo, setSaldo] = useState(0);
  const [rewards, setRewards] = useState([]);
  const [dark, setDark] = useState(false);
  const [showAdd, setShowAdd] = useState(false);
  const [rewardName, setRewardName] = useState('');
  const [rewardCost, setRewardCost] = useState('');
  const [sobrePg, setSobrePg] = useState(0);
  const [dialog, setDialog] = useState(null);
  const [toast, setToast] = useState('');
  const [floatAmount, setFloatAmount] = useState(null);
  const [, setTimerVersion] = useState(0);

  const scrollRef = useRef(null);
  const toastTimerRef = useRef(null);
  const timerIntervalRef = useRef(null);
  const pageAnim = useRef(new Animated.Value(1)).current;
  const toastAnim = useRef(new Animated.Value(0)).current;
  const floatAnim = useRef(new Animated.Value(0)).current;
  const themeAnim = useRef(new Animated.Value(0)).current;
  const starAnim = useRef(new Animated.Value(0)).current;
  const stars = useMemo(makeStars, []);
  const pomoRef = useRef({
    work: 25,
    rest: 5,
    remaining: 0,
    total: 0,
    isWork: true,
    running: false,
  });

  const t = dark ? DARK : LIGHT;
  const styles = useMemo(() => createStyles(t, dark), [t, dark]);

  useEffect(() => {
    (async () => {
      try {
        const pairs = await AsyncStorage.multiGet([LS_SALDO, LS_REWARDS, LS_THEME]);
        const map = Object.fromEntries(pairs);
        const parsedSaldo = parseInt(map[LS_SALDO] || '0', 10) || 0;
        let parsedRewards = [];
        try {
          parsedRewards = JSON.parse(map[LS_REWARDS] || '[]');
          if (!Array.isArray(parsedRewards)) parsedRewards = [];
        } catch {
          parsedRewards = [];
        }
        const isDark = map[LS_THEME] === 'dark';
        setSaldo(Math.max(0, parsedSaldo));
        setRewards(parsedRewards);
        setDark(isDark);
        themeAnim.setValue(isDark ? 1 : 0);
      } finally {
        setLoaded(true);
      }
    })();

    return () => {
      if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
      if (timerIntervalRef.current) clearInterval(timerIntervalRef.current);
    };
  }, [themeAnim]);

  useEffect(() => {
    pageAnim.setValue(0);
    Animated.timing(pageAnim, {
      toValue: 1,
      duration: 300,
      easing: Easing.out(Easing.ease),
      useNativeDriver: true,
    }).start();
    requestAnimationFrame(() => scrollRef.current?.scrollTo({ y: 0, animated: false }));
  }, [page, pageAnim]);

  useEffect(() => {
    if (!dark) {
      starAnim.stopAnimation();
      starAnim.setValue(0);
      return undefined;
    }
    const loop = Animated.loop(
      Animated.sequence([
        Animated.timing(starAnim, { toValue: 1, duration: 1600, easing: Easing.inOut(Easing.ease), useNativeDriver: true }),
        Animated.timing(starAnim, { toValue: 0, duration: 1600, easing: Easing.inOut(Easing.ease), useNativeDriver: true }),
      ]),
    );
    loop.start();
    return () => loop.stop();
  }, [dark, starAnim]);

  const persistSaldo = (next) => {
    const safe = Math.max(0, next);
    setSaldo(safe);
    AsyncStorage.setItem(LS_SALDO, String(safe));
  };

  const changeSaldo = (amount) => {
    setSaldo((current) => {
      const next = Math.max(0, current + amount);
      AsyncStorage.setItem(LS_SALDO, String(next));
      return next;
    });
  };

  const persistRewards = (next) => {
    setRewards(next);
    AsyncStorage.setItem(LS_REWARDS, JSON.stringify(next));
  };

  const showToast = (msg, dur = 2200) => {
    setToast(msg);
    if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
    toastAnim.stopAnimation();
    toastAnim.setValue(0);
    Animated.timing(toastAnim, {
      toValue: 1,
      duration: 250,
      easing: Easing.out(Easing.ease),
      useNativeDriver: true,
    }).start();
    toastTimerRef.current = setTimeout(() => {
      Animated.timing(toastAnim, {
        toValue: 0,
        duration: 250,
        easing: Easing.in(Easing.ease),
        useNativeDriver: true,
      }).start(() => setToast(''));
    }, dur);
  };

  const floatPoints = (amount) => {
    setFloatAmount(amount);
    floatAnim.stopAnimation();
    floatAnim.setValue(0);
    Animated.timing(floatAnim, {
      toValue: 1,
      duration: 900,
      easing: Easing.out(Easing.ease),
      useNativeDriver: true,
    }).start(() => setFloatAmount(null));
  };

  const goPage = (nextPage) => {
    setPage(nextPage);
  };

  const closeModal = () => setDialog(null);

  const openConfirm = (title, body, onConfirm) => {
    setDialog({
      title,
      body,
      confirmLabel: 'Confirmar',
      showCancel: true,
      onConfirm: () => {
        setDialog(null);
        onConfirm();
      },
    });
  };

  const openInfo = (title, body, confirmLabel = 'Entendi') => {
    setDialog({
      title,
      body,
      confirmLabel,
      showCancel: false,
      onConfirm: () => setDialog(null),
    });
  };

  const openHowToModal = () => {
    openInfo(
      'Como Usar',
      <View>
        <Text style={styles.modalParagraph}>1. Toque em <Text style={styles.modalStrong}>Pomodoro</Text> na página inicial e escolha um timer para iniciar.</Text>
        <Text style={styles.modalParagraph}>2. Fique focado durante o tempo de trabalho para ganhar <Text style={styles.modalStrong}>+1 ponto por minuto</Text>.</Text>
        <Text style={styles.modalParagraph}>3. Use os pontos acumulados para resgatar recompensas que voce mesmo cadastrar aqui.</Text>
        <View style={{ height: 8 }} />
        <Text style={styles.modalParagraph}><Text style={styles.modalStrong}>Exemplo: 50 pontos = 50 minutos.</Text> Logo, cabe a você (usuário), definir a sua própria recompensa e o seu custo, como <Text style={styles.modalStrong}>"Assistir um filme"</Text>, por volta de <Text style={styles.modalStrong}>60 pontos</Text> por ser uma atividade que dura mais de 60 minutos (1 hora).</Text>
      </View>,
    );
  };

  const toggleAddForm = () => {
    if (rewards.length >= MAX_REWARDS) {
      showToast('Limite de 3 recompensas atingido');
      return;
    }
    setShowAdd((open) => {
      const next = !open;
      if (next) {
        setRewardName('');
        setRewardCost('');
      }
      return next;
    });
  };

  const addReward = () => {
    const name = rewardName.trim();
    const cost = parseInt(rewardCost, 10);
    if (!name) {
      showToast('Digite o nome da recompensa');
      return;
    }
    if (!cost || cost < 1) {
      showToast('Digite um custo valido');
      return;
    }
    if (rewards.length >= MAX_REWARDS) {
      showToast('Limite de 3 recompensas atingido');
      return;
    }
    persistRewards([...rewards, { id: Date.now(), name, cost }]);
    setShowAdd(false);
    showToast('Recompensa salva');
  };

  const deleteReward = (id) => {
    const reward = rewards.find((x) => x.id === id);
    if (!reward) return;
    openConfirm(
      'Excluir',
      <Text style={styles.modalText}>Excluir <Text style={styles.modalStrong}>"{reward.name}"</Text>?</Text>,
      () => {
        persistRewards(rewards.filter((x) => x.id !== id));
        showToast('Recompensa excluida');
      },
    );
  };

  const redeemReward = (id) => {
    const reward = rewards.find((x) => x.id === id);
    if (!reward) return;
    if (saldo < reward.cost) {
      showToast(`Saldo insuficiente (faltam ${reward.cost - saldo} pts)`);
      return;
    }
    openConfirm(
      'Resgatar',
      <Text style={styles.modalText}>Resgatar <Text style={styles.modalStrong}>"{reward.name}"</Text> por <Text style={styles.modalStrong}>{reward.cost} pts</Text>?</Text>,
      () => {
        persistSaldo(saldo - reward.cost);
        floatPoints(-reward.cost);
        persistRewards(rewards.filter((x) => x.id !== id));
        showToast(`"${reward.name}" resgatada!`, 2800);
      },
    );
  };

  const bumpTimer = () => setTimerVersion((v) => v + 1);

  const clearTimerInterval = () => {
    if (timerIntervalRef.current) clearInterval(timerIntervalRef.current);
    timerIntervalRef.current = null;
  };

  const pauseTimer = () => {
    pomoRef.current.running = false;
    clearTimerInterval();
    bumpTimer();
  };

  const resumeTimer = () => {
    if (pomoRef.current.running) return;
    pomoRef.current.running = true;
    clearTimerInterval();
    timerIntervalRef.current = setInterval(() => {
      const pomo = pomoRef.current;
      if (pomo.remaining <= 0) {
        clearTimerInterval();
        pomo.running = false;
        if (pomo.isWork) {
          changeSaldo(1);
          floatPoints(1);
        }
        pomo.isWork = !pomo.isWork;
        pomo.remaining = (pomo.isWork ? pomo.work : pomo.rest) * 60;
        pomo.total = pomo.remaining;
        bumpTimer();
        setTimeout(() => resumeTimer(), 0);
        return;
      }

      pomo.remaining -= 1;
      if (pomo.isWork && pomo.remaining > 0 && pomo.remaining % 60 === 0) {
        changeSaldo(1);
        floatPoints(1);
      }
      bumpTimer();
    }, 1000);
    bumpTimer();
  };

  const toggleTimer = () => {
    if (pomoRef.current.running) pauseTimer();
    else resumeTimer();
  };

  const startPomodoro = (work, rest) => {
    clearTimerInterval();
    pomoRef.current = {
      work,
      rest,
      remaining: work * 60,
      total: work * 60,
      isWork: true,
      running: false,
    };
    setPage('timer');
    bumpTimer();
    setTimeout(() => resumeTimer(), 0);
  };

  const confirmLeaveTimer = () => {
    openConfirm(
      'Sair do Timer',
      <Text style={styles.modalText}>O progresso da sessao atual sera perdido. Seus pontos ja ganhos foram salvos.</Text>,
      () => {
        clearTimerInterval();
        pomoRef.current.running = false;
        goPage('pomodoro');
        bumpTimer();
      },
    );
  };

  const changeSobrePg = (dir) => {
    setSobrePg((current) => Math.max(0, Math.min(3, current + dir)));
  };

  const copiarPix = async () => {
    try {
      await Clipboard.setStringAsync(CHAVE_PIX);
      showToast('Chave PIX copiada');
    } catch {
      showToast('Chave PIX copiada');
    }
  };

  const assistirAD = () => {
    Linking.openURL('https://www.youtube.com/watch?v=xvFZjo5PgG0');
  };

  const toggleTheme = () => {
    const next = !dark;
    setDark(next);
    AsyncStorage.setItem(LS_THEME, next ? 'dark' : 'light');
    Animated.timing(themeAnim, {
      toValue: next ? 1 : 0,
      duration: 450,
      easing: Easing.out(Easing.back(1.2)),
      useNativeDriver: false,
    }).start();
  };

  const Balance = () => (
    <View style={styles.balanceWrap}>
      <View style={styles.balancePill}>
        <Text style={styles.balanceNumber}>{saldo}</Text>
        <Text style={styles.balanceLabel}>pts</Text>
      </View>
      {floatAmount !== null && (
        <Animated.Text
          pointerEvents="none"
          style={[
            styles.ptsFloat,
            {
              opacity: floatAnim.interpolate({ inputRange: [0, 0.7, 1], outputRange: [1, 1, 0] }),
              transform: [{ translateY: floatAnim.interpolate({ inputRange: [0, 0.7, 1], outputRange: [0, -22, -30] }) }],
            },
          ]}
        >
          {floatAmount > 0 ? '+' : ''}{floatAmount} pts
        </Animated.Text>
      )}
    </View>
  );

  const Divider = () => <View style={styles.rule} />;

  const BackButton = ({ onPress }) => (
    <Pressable onPress={onPress} style={({ pressed }) => [styles.backBtn, pressed && styles.pressDark]}>
      <AppIcon type="left" size={16} color={t.ink2} strokeWidth={2.5} />
    </Pressable>
  );

  const SectionHeader = ({ title, balance = false, onBack }) => (
    <>
      <View style={styles.sectionHead}>
        <BackButton onPress={onBack} />
        <Text style={styles.sectionTitle}>{title}</Text>
        {balance ? <Balance /> : <View style={{ width: 36 }} />}
      </View>
      <Divider />
    </>
  );

  const ThemeToggle = () => {
    const knobLeft = themeAnim.interpolate({ inputRange: [0, 1], outputRange: [4, 36] });
    const dayOpacity = themeAnim.interpolate({ inputRange: [0, 1], outputRange: [1, 0] });
    const nightOpacity = themeAnim.interpolate({ inputRange: [0, 1], outputRange: [0, 1] });
    const sunOpacity = themeAnim.interpolate({ inputRange: [0, 1], outputRange: [1, 0] });
    const moonOpacity = themeAnim.interpolate({ inputRange: [0, 1], outputRange: [0, 1] });
    return (
      <Pressable onPress={toggleTheme} style={styles.themeSlider} accessibilityRole="button" accessibilityLabel="Alternar tema">
        <Animated.View style={[StyleSheet.absoluteFillObject, { opacity: dayOpacity }]}>
          <LinearGradient colors={['#7ecef4', '#ffe680']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={StyleSheet.absoluteFillObject} />
        </Animated.View>
        <Animated.View style={[StyleSheet.absoluteFillObject, { opacity: nightOpacity }]}>
          <LinearGradient colors={['#060e18', '#081a10']} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={StyleSheet.absoluteFillObject} />
          <View style={[styles.miniStar, { width: 2, height: 2, top: 7, left: 10 }]} />
          <View style={[styles.miniStar, { width: 3, height: 3, top: 19, left: 18 }]} />
          <View style={[styles.miniStar, { width: 2, height: 2, top: 12, left: 28 }]} />
          <View style={[styles.miniStar, { width: 2, height: 2, top: 22, left: 8 }]} />
        </Animated.View>
        <Animated.View style={[styles.themeKnob, dark && styles.themeKnobDark, { left: knobLeft }]}>
          <Animated.View style={[styles.themeIconLayer, { opacity: sunOpacity }]}>
            <AppIcon type="sun" size={14} color="#f59e0b" strokeWidth={2.5} />
          </Animated.View>
          <Animated.View style={[styles.themeIconLayer, { opacity: moonOpacity }]}>
            <AppIcon type="moon" size={14} color="#a5c8f0" strokeWidth={2.5} />
          </Animated.View>
        </Animated.View>
      </Pressable>
    );
  };

  const Footer = ({ home = false }) => (
    <View style={[styles.footerBar, !home && styles.footerCentered]}>
      {home ? (
        <>
          <Pressable onPress={() => goPage('apoie')} style={({ pressed }) => [styles.footerBtn, pressed && styles.footerBtnPressed]}>
            <Text style={styles.footerBtnText}>♥ Apoie</Text>
          </Pressable>
          <Text style={styles.footerCopy}>© +Foco</Text>
          <ThemeToggle />
        </>
      ) : (
        <Text style={styles.footerCopy}>© +Foco</Text>
      )}
    </View>
  );

  const InfoStrip = ({ children }) => <View style={styles.infoStrip}><Text style={styles.infoStripText}>{children}</Text></View>;

  const Home = () => (
    <View style={styles.page}>
      <View style={styles.topbar}>
        <Text style={styles.logo}><Text style={styles.logoPlus}>+</Text>FOCO</Text>
        <Balance />
      </View>
      <Divider />

      <View style={styles.hero}>
        <LinearGradient
          colors={['rgba(34,192,100,0.15)', 'rgba(34,192,100,0)']}
          start={{ x: 0, y: 0 }}
          end={{ x: 1, y: 1 }}
          style={StyleSheet.absoluteFillObject}
        />
        <Text style={styles.heroGhost}>+FOCO</Text>
        <Text style={styles.heroLabel}>Bem-vindo ao +Foco</Text>
        <Text style={styles.heroTitle}>Controle o seu{`\n`}<Text style={styles.heroTitleEm}>foco</Text> e ganhe pontos</Text>
        <Text style={styles.heroSub}>Use o Pomodoro para acumular pontos e resgate recompensas personalizadas.</Text>
      </View>

      <View style={styles.navGrid}>
        <Pressable onPress={() => goPage('rewards')} style={({ pressed }) => [styles.navCardFull, pressed && styles.cardPressed]}>
          <View style={[styles.navIcon, styles.navIconFull]}><AppIcon type="star" size={19} color={t.accent} /></View>
          <View style={{ flex: 1 }}>
            <Text style={styles.navLabel}>Minhas Recompensas</Text>
            <Text style={styles.navSub}>Cadastre e resgate recompensas</Text>
          </View>
          <Text style={styles.navArrow}>›</Text>
        </Pressable>

        <View style={styles.navRow}>
          <Pressable onPress={() => goPage('pomodoro')} style={({ pressed }) => [styles.navCardHalf, pressed && styles.cardPressed]}>
            <View style={styles.navIcon}><AppIcon type="timer" size={19} color={t.ink2} /></View>
            <Text style={styles.navLabel}>Pomodoro</Text>
            <Text style={styles.navSub}>Timer de foco</Text>
            <View style={styles.navBadge}><Text style={styles.navBadgeText}>+1 pts/min</Text></View>
          </Pressable>

          <Pressable onPress={() => goPage('sobre')} style={({ pressed }) => [styles.navCardHalf, pressed && styles.cardPressed]}>
            <View style={styles.navIcon}><AppIcon type="info" size={19} color={t.ink2} /></View>
            <Text style={styles.navLabel}>Sobre Nos</Text>
            <Text style={styles.navSub}>O projeto +FOCO</Text>
          </Pressable>
        </View>
      </View>

      <Footer home />
    </View>
  );

  const Pomodoro = () => (
    <View style={styles.page}>
      <SectionHeader title="Pomodoro" balance onBack={() => goPage('home')} />
      <Text style={styles.chooseTimer}>Escolha seu timer</Text>
      <View style={styles.pomoOptions}>
        <Pressable onPress={() => startPomodoro(25, 5)} style={({ pressed }) => [styles.pomoCard, pressed && styles.cardPressed]}>
          <AppIcon type="timer" size={40} color={t.ink2} />
          <Text style={styles.pomoName}>Rapido</Text>
          <Text style={styles.pomoDur}>25/5</Text>
          <Text style={styles.pomoHint}>min foco / descanso</Text>
        </Pressable>
        <Pressable onPress={() => startPomodoro(50, 10)} style={({ pressed }) => [styles.pomoCard, pressed && styles.cardPressed]}>
          <AppIcon type="timer" size={40} color={t.ink2} />
          <Text style={styles.pomoName}>Longo</Text>
          <Text style={styles.pomoDur}>50/10</Text>
          <Text style={styles.pomoHint}>min foco / descanso</Text>
        </Pressable>
      </View>
      <InfoStrip>Ganhe <Text style={styles.infoStrong}>+1 ponto</Text> a cada minuto completo de trabalho focado.</InfoStrip>
      <Footer />
    </View>
  );

  const TimerPage = () => {
    const pomo = pomoRef.current;
    const mins = Math.floor(pomo.remaining / 60);
    const secs = pomo.remaining % 60;
    const pct = pomo.total ? 1 - pomo.remaining / pomo.total : 0;
    const dashOffset = RING_CIRCUMFERENCE - pct * RING_CIRCUMFERENCE;
    return (
      <View style={styles.page}>
        <SectionHeader title="Em Foco" balance onBack={confirmLeaveTimer} />
        <View style={styles.timerWrap}>
          <LinearGradient
            colors={['rgba(34,192,100,0.12)', 'rgba(34,192,100,0)']}
            start={{ x: 0.5, y: 0 }}
            end={{ x: 0.5, y: 0.8 }}
            style={StyleSheet.absoluteFillObject}
          />
          <Text style={styles.timerPhase}>{pomo.isWork ? 'TEMPO DE TRABALHO' : 'TEMPO DE DESCANSO'}</Text>
          <Text style={[styles.timerClock, !pomo.isWork && styles.timerClockRest]}>{mins}:{secs < 10 ? '0' : ''}{secs}</Text>
          <Text style={styles.timerSub}>{pomo.isWork ? `${pomo.work} min de foco` : `${pomo.rest} min de descanso`}</Text>
          <Svg width={110} height={110} viewBox="0 0 110 110" style={{ marginBottom: 26 }}>
            <Circle cx="55" cy="55" r="46" fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth="7" />
            <Circle
              cx="55"
              cy="55"
              r="46"
              fill="none"
              stroke={pomo.isWork ? 'rgba(34,192,100,0.9)' : 'rgba(255,255,255,0.25)'}
              strokeWidth="7"
              strokeLinecap="round"
              strokeDasharray={[RING_CIRCUMFERENCE, RING_CIRCUMFERENCE]}
              strokeDashoffset={dashOffset}
              rotation="-90"
              origin="55, 55"
            />
          </Svg>
          <View style={styles.timerControls}>
            <Pressable onPress={confirmLeaveTimer} style={({ pressed }) => [styles.timerBtn, styles.stopBtn, pressed && styles.roundPressed]}>
              <AppIcon type="stop" size={20} color="rgba(255,255,255,0.6)" />
            </Pressable>
            <Pressable onPress={toggleTimer} style={({ pressed }) => [styles.timerBtn, styles.pauseBtn, pressed && styles.roundPressed]}>
              <AppIcon type={pomo.running ? 'pause' : 'play'} size={20} color="rgba(255,255,255,0.85)" />
            </Pressable>
          </View>
        </View>
        <InfoStrip>Mantenha o foco ate o fim do ciclo para maximizar seus pontos.</InfoStrip>
        <Footer />
      </View>
    );
  };

  const Rewards = () => {
    const count = rewards.length;
    return (
      <View style={styles.page}>
        <SectionHeader title="Recompensas" balance onBack={() => goPage('home')} />
        <View style={styles.rewardsHeader}>
          <Text style={styles.rewardsCount}>{count} / {MAX_REWARDS}</Text>
          <Pressable onPress={openHowToModal} style={({ pressed }) => [styles.addRewardBtn, pressed && styles.addRewardBtnPressed]}>
            <AppIcon type="info" size={14} color={dark ? '#06150c' : '#fff'} strokeWidth={2.5} />
            <Text style={styles.addRewardBtnText}>Como usar?</Text>
          </Pressable>
          <Pressable onPress={toggleAddForm} style={({ pressed }) => [styles.addRewardBtn, count >= MAX_REWARDS && styles.disabledBtn, pressed && count < MAX_REWARDS && styles.addRewardBtnPressed]}>
            <AppIcon type="plus" size={14} color={dark ? '#06150c' : '#fff'} strokeWidth={2.5} />
            <Text style={styles.addRewardBtnText}>Nova</Text>
          </Pressable>
        </View>

        {showAdd && (
          <View style={styles.addForm}>
            <Text style={styles.formLabel}>Nova Recompensa</Text>
            <View style={styles.inputRow}>
              <TextInput
                value={rewardName}
                onChangeText={setRewardName}
                placeholder="Nome da recompensa"
                placeholderTextColor={t.ink3}
                maxLength={30}
                style={styles.input}
                autoFocus
              />
              <TextInput
                value={rewardCost}
                onChangeText={(value) => setRewardCost(value.replace(/[^0-9]/g, '').slice(0, 4))}
                placeholder="Pts"
                placeholderTextColor={t.ink3}
                keyboardType="number-pad"
                style={[styles.input, styles.inputShort]}
              />
            </View>
            <View style={styles.formActions}>
              <Pressable onPress={addReward} style={({ pressed }) => [styles.confirmBtn, pressed && styles.confirmBtnPressed]}><Text style={styles.confirmBtnText}>Salvar</Text></Pressable>
              <Pressable onPress={toggleAddForm} style={({ pressed }) => [styles.cancelBtn, pressed && { opacity: 0.7 }]}><Text style={styles.cancelBtnText}>Cancelar</Text></Pressable>
            </View>
          </View>
        )}

        <View style={styles.rewardsList}>
          {count === 0 ? (
            <View style={styles.emptyRewards}>
              <Text style={styles.emptyBig}>Nenhuma ainda.</Text>
              <Text style={styles.emptyText}>Clique em <Text style={{ fontFamily: FONT.bodySemi, color: t.ink }}>+ Nova</Text> para criar sua primeira recompensa.</Text>
            </View>
          ) : rewards.map((reward) => (
            <View key={reward.id} style={styles.rewardItem}>
              <View style={styles.rewardIcon}><AppIcon type="star" size={18} color={t.ink2} /></View>
              <View style={styles.rewardInfo}>
                <Text numberOfLines={1} style={styles.rewardName}>{reward.name}</Text>
                <Text style={styles.rewardCost}>{reward.cost} pontos</Text>
              </View>
              <View style={styles.rewardActions}>
                <Pressable onPress={() => deleteReward(reward.id)} style={({ pressed }) => [styles.rewardActionBtn, pressed && styles.deletePressed]}>
                  <AppIcon type="close" size={14} color={t.ink2} strokeWidth={2.5} />
                </Pressable>
                <Pressable onPress={() => redeemReward(reward.id)} style={({ pressed }) => [styles.rewardActionBtn, pressed && styles.buyPressed]}>
                  <AppIcon type="check" size={14} color={t.ink2} strokeWidth={2.5} />
                </Pressable>
              </View>
            </View>
          ))}
        </View>

        <Text style={styles.limitNote}>{count >= MAX_REWARDS ? 'Limite maximo atingido. Resgate ou exclua uma recompensa para adicionar outra.' : ''}</Text>
        <Footer />
      </View>
    );
  };

  const Apoie = () => (
    <View style={styles.page}>
      <SectionHeader title="Apoie o Projeto" onBack={() => goPage('home')} />
      <View style={styles.pixCard}>
        <Text style={styles.pixLead}>Escaneie ou copie a chave PIX</Text>
        <View style={styles.qrFrame}><Image source={{ uri: QR_URI }} style={styles.qrImage} resizeMode="contain" /></View>
        <Pressable onPress={copiarPix} style={({ pressed }) => [styles.pixBtn, pressed && styles.pixBtnPressed]}>
          <AppIcon type="copy" size={16} color={dark ? '#06150c' : 'rgba(255,255,255,0.7)'} strokeWidth={2.5} />
          <Text style={styles.pixBtnText}>Copiar Chave PIX</Text>
        </Pressable>
        <Text style={styles.pixKey}>{CHAVE_PIX}</Text>
      </View>
      <Pressable onPress={assistirAD} style={({ pressed }) => [styles.adBtn, pressed && styles.adBtnPressed]}>
        <AppIcon type="play" size={17} color={t.ink3} />
        <Text style={styles.adBtnText}>Assistir anuncio para apoiar</Text>
      </Pressable>
      <InfoStrip>Seu apoio ajuda a manter o +FOCO gratuito e em constante evolucao. Obrigado! ♥</InfoStrip>
      <Footer />
    </View>
  );

  const Sobre = () => {
    const pages = [
      <View key="0" style={styles.sobreCard}>
        <Text style={styles.sobreParagraph}><Text style={styles.sobreStrong}>Projeto UniLaSalle — RJ</Text></Text>
        <Text style={styles.sobreParagraph}>O +FOCO foi idealizado e realizado por Enzo Carvalho Martins e Felipe Mitraud Kraft da Universidade UniLaSalle com o objetivo de conscientizar sobre o uso excessivo de telas.</Text>
        <Text style={styles.sobreParagraph}>Através de recursos como monitoramento em tempo real e metas personalizáveis, buscamos promover a saúde digital de forma prática e intuitiva.</Text>
        <Text style={[styles.sobreParagraph, { marginBottom: 0 }]}>Nosso app pode te auxiliar caso voce enfrente déficits cognitivos, distúrbios do sono, problemas visuais, ansiedade, estresse ou depressão. Sempre recomendamos buscar um profissional de saude.</Text>
      </View>,
      <View key="1" style={styles.sobreCard}>
        <Text style={styles.sobreParagraph}><Text style={styles.sobreStrong}>O Impacto das Telas</Text></Text>
        <Text style={styles.sobreParagraph}>Uma pesquisa de 2023 do Jornal da USP apontou que a população brasileira passa, em média, 56,6% do dia (cerca de 9 horas) em frente as telas, relatando maior frequência de sintomas de transtornos.</Text>
        <Bullet styles={styles} t={t}><Text style={styles.sobreStrong}>Déficits Cognitivos</Text> — Diminuição da memória, dificuldade de concentração e prejuízo na capacidade de planejar.</Bullet>
        <Bullet styles={styles} t={t}><Text style={styles.sobreStrong}>Distúrbios do Sono</Text> — A luz azul atrasa o descanso e prejudica o desempenho no dia seguinte.</Bullet>
      </View>,
      <View key="2" style={styles.sobreCard}>
        <Text style={styles.sobreParagraph}><Text style={styles.sobreStrong}>Mais Sintomas do Excesso de Telas</Text></Text>
        <Bullet styles={styles} t={t}><Text style={styles.sobreStrong}>Problemas Emocionais</Text> — Ansiedade, estresse e depressão, especialmente pelo uso de redes sociais.</Bullet>
        <Bullet styles={styles} t={t}><Text style={styles.sobreStrong}>Danos a Visão</Text> — Fadiga ocular, olhos secos e dores de cabeca.</Bullet>
        <Bullet styles={styles} t={t}><Text style={styles.sobreStrong}>Sedentarismo</Text> — Postura inadequada levando a dores musculares e problemas ortopédicos.</Bullet>
        <Bullet styles={styles} t={t}><Text style={styles.sobreStrong}>Desenvolvimento Infantil</Text> — Atrasos na linguagem e risco aumentado de TDAH em criancas.</Bullet>
      </View>,
      <View key="3" style={styles.sobreCard}>
        <Text style={styles.sobreParagraph}><Text style={styles.sobreStrong}>Agradecimentos</Text></Text>
        <Text style={styles.sobreParagraph}>Felipe Mitraud Kraft e Enzo Carvalho Martins agradecem imensamente a todas as pessoas que utilizam o +FOCO e aproveitam suas funcionalidades no dia a dia.</Text>
        <Text style={styles.sobreParagraph}>Agradecemos também, de coração, o apoio e auxílio dos professores e instrutores Alexandre Neves Louzada e Lauro Victor Ramos Cavadas, fundamentais para a realização deste projeto.</Text>
        <Text style={[styles.sobreParagraph, { marginBottom: 0 }]}>O +FOCO nasceu como Trabalho de Conclusão de Curso (TCC) dos alunos Enzo e Felipe, e chegar até aqui só foi possível graças a todo esse apoio. Muito obrigado! ♥</Text>
      </View>,
    ];

    return (
      <View style={styles.page}>
        <SectionHeader title="Sobre Nos" onBack={() => goPage('home')} />
        <View style={styles.sobreNav}>
          <Pressable disabled={sobrePg === 0} onPress={() => changeSobrePg(-1)} style={({ pressed }) => [styles.navArrowBtn, sobrePg === 0 && styles.navArrowDisabled, pressed && styles.pressDark]}>
            <AppIcon type="left" size={14} color={t.ink2} strokeWidth={2.5} />
          </Pressable>
          <View style={styles.pgDots}>
            {[0, 1, 2, 3].map((dot) => <View key={dot} style={[styles.dot, sobrePg === dot && styles.dotActive]} />)}
          </View>
          <Pressable disabled={sobrePg === 3} onPress={() => changeSobrePg(1)} style={({ pressed }) => [styles.navArrowBtn, sobrePg === 3 && styles.navArrowDisabled, pressed && styles.pressDark]}>
            <AppIcon type="right" size={14} color={t.ink2} strokeWidth={2.5} />
          </Pressable>
        </View>
        {pages[sobrePg]}
        <Footer />
      </View>
    );
  };

  const renderPage = () => {
    if (page === 'pomodoro') return <Pomodoro />;
    if (page === 'timer') return <TimerPage />;
    if (page === 'rewards') return <Rewards />;
    if (page === 'apoie') return <Apoie />;
    if (page === 'sobre') return <Sobre />;
    return <Home />;
  };

  if (!fontsLoaded || !loaded) {
    return (
      <View style={[styles.loading, { backgroundColor: t.bg }]}>
        <ActivityIndicator color={t.accent} />
      </View>
    );
  }

  return (
    <SafeAreaView style={styles.safeArea}>
      <StatusBar barStyle={dark ? 'light-content' : 'dark-content'} backgroundColor={t.bg} />
      <KeyboardAvoidingView style={styles.flex1} behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
        <View style={styles.root}>
          <View pointerEvents="none" style={styles.bgOrbOne} />
          <View pointerEvents="none" style={styles.bgOrbTwo} />
          {dark && (
            <Animated.View
              pointerEvents="none"
              style={[
                StyleSheet.absoluteFillObject,
                { opacity: starAnim.interpolate({ inputRange: [0, 1], outputRange: [0.68, 1] }) },
              ]}
            >
              {stars.map((star) => (
                <View
                  key={star.id}
                  style={[
                    styles.star,
                    {
                      left: star.left,
                      top: star.top,
                      width: star.size,
                      height: star.size,
                      opacity: star.opacity,
                    },
                  ]}
                >
                  {star.sparkle && (
                    <>
                      <View style={[styles.sparkleV, { height: star.size * 2 }]} />
                      <View style={[styles.sparkleH, { width: star.size * 2 }]} />
                    </>
                  )}
                </View>
              ))}
            </Animated.View>
          )}

          <ScrollView
            ref={scrollRef}
            keyboardShouldPersistTaps="handled"
            showsVerticalScrollIndicator={false}
            contentContainerStyle={styles.scrollContent}
          >
            <Animated.View
              style={[
                styles.app,
                {
                  opacity: pageAnim,
                  transform: [{ translateY: pageAnim.interpolate({ inputRange: [0, 1], outputRange: [14, 0] }) }],
                },
              ]}
            >
              {renderPage()}
            </Animated.View>
          </ScrollView>
        </View>
      </KeyboardAvoidingView>

      <Modal transparent visible={!!dialog} animationType="fade" onRequestClose={closeModal}>
        <View style={styles.modalOverlay}>
          <View style={styles.modalBox}>
            <Text style={styles.modalTitle}>{dialog?.title}</Text>
            <View style={styles.modalBody}>{dialog?.body}</View>
            <View style={styles.modalActions}>
              {dialog?.showCancel && (
                <Pressable onPress={closeModal} style={({ pressed }) => [styles.modalBtnSecondary, pressed && { opacity: 0.75 }]}>
                  <Text style={styles.modalBtnSecondaryText}>Cancelar</Text>
                </Pressable>
              )}
              <Pressable onPress={dialog?.onConfirm} style={({ pressed }) => [styles.modalBtnPrimary, pressed && styles.modalBtnPrimaryPressed]}>
                <Text style={styles.modalBtnPrimaryText}>{dialog?.confirmLabel}</Text>
              </Pressable>
            </View>
          </View>
        </View>
      </Modal>

      {!!toast && (
        <Animated.View
          pointerEvents="none"
          style={[
            styles.toast,
            {
              opacity: toastAnim,
              transform: [{ translateY: toastAnim.interpolate({ inputRange: [0, 1], outputRange: [10, 0] }) }],
            },
          ]}
        >
          <Text style={styles.toastText}>{toast}</Text>
        </Animated.View>
      )}
    </SafeAreaView>
  );
}

function Bullet({ children, styles, t }) {
  return (
    <View style={styles.bulletRow}>
      <Text style={[styles.bulletDot, { color: t.ink2 }]}>•</Text>
      <Text style={styles.bulletText}>{children}</Text>
    </View>
  );
}

