    heroLabel: { fontFamily: FONT.mono, fontSize: 10, color: 'rgba(255,255,255,0.4)', textTransform: 'uppercase', letterSpacing: 2.5, marginBottom: 10 },
    heroTitle: { fontFamily: FONT.serif, fontSize: 30, fontWeight: '400', lineHeight: 34.5, color: '#fff', marginBottom: 14 },
